local ReaperMaker = {}
local PRODUCTS = {
    simple_wood_reaper = { name = "Preprost leseni žetveni stroj", woodCost = 5, ironCost = 2, time = 6, cost = 180, food = 25, happiness = 1, description = "Preprost leseni žetveni stroj za žetev." },
    iron_blade_reaper = { name = "Železnorezni žetveni stroj", woodCost = 4, ironCost = 3, time = 9, cost = 440, food = 40, happiness = 2, prestige = 2, description = "Železnorezni žetveni stroj za trgovce." },
    silver_geared_reaper = { name = "Srebrnozobčani žetveni stroj", woodCost = 4, silverCost = 1, ironCost = 3, time = 13, cost = 1000, food = 55, happiness = 2, prestige = 6, description = "Srebrnozobčani žetveni stroj za plemiče." },
    gold_trimmed_reaper = { name = "Zlatookrasni žetveni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, time = 17, cost = 2300, food = 72, happiness = 3, prestige = 14, description = "Zlatookrasni žetveni stroj za visoke plemiče." },
    jewel_set_reaper = { name = "Draguljasta žetveni stroj", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 3, jewelCost = 1, time = 21, cost = 5000, food = 88, happiness = 5, prestige = 27, description = "Žetveni stroj z draguljem za visoko plemstvo." },
    royal_grand_reaper = { name = "Kraljevski veliki žetveni stroj", woodCost = 6, goldCost = 2, silverCost = 2, ironCost = 3, jewelCost = 2, pearlCost = 2, time = 28, cost = 10500, food = 100, happiness = 12, prestige = 58, description = "Veliki kraljevski žetveni stroj z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    reaper_workshop = { name = "Žetvena delavnica", cost = { gold = 300, wood = 180, stone = 140, iron = 8 }, upkeep = 7, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 1100, wood = 320, stone = 280, silver = 6, iron = 8 }, upkeep = 25, qualityBonus = 18 },
    master_reaper_atelier = { name = "Mojstrski žetveni atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
ReaperMaker.woodStock = 22; ReaperMaker.ironStock = 14; ReaperMaker.silverStock = 6; ReaperMaker.goldStock = 6; ReaperMaker.jewelStock = 4; ReaperMaker.pearlStock = 4
ReaperMaker.productStock = {}; ReaperMaker.buildings = {}; ReaperMaker.maker = nil; ReaperMaker.activeMaking = {}; ReaperMaker.totalProducts = 0; ReaperMaker.dayTimer = 0
function ReaperMaker.init() ReaperMaker.woodStock=22; ReaperMaker.ironStock=14; ReaperMaker.silverStock=6; ReaperMaker.goldStock=6; ReaperMaker.jewelStock=4; ReaperMaker.pearlStock=4; ReaperMaker.productStock={}; ReaperMaker.buildings={}; ReaperMaker.maker=nil; ReaperMaker.activeMaking={}; ReaperMaker.totalProducts=0; ReaperMaker.dayTimer=0; print("[ReaperMaker] Royal Reaper Maker System initialized (6 products, 4 buildings)") end
function ReaperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ReaperMaker.maker={name=n or ("Žetveni strojar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žetveni strojar najet: %s (spretnost: %d)",ReaperMaker.maker.name,s),"success") end; return true end
function ReaperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ReaperMaker.build(id) local ok,e=ReaperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ReaperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ReaperMaker.getQualityBonus() local b=0; for _,bd in ipairs(ReaperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ReaperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ReaperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and ReaperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.silverCost and ReaperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ReaperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ReaperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ReaperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ReaperMaker.buildings==0 then return false,"Potrebna žetvena delavnica" end; if not ReaperMaker.maker then return false,"Potreben žetveni strojar" end; return true end
function ReaperMaker.make(pt,qty) qty=qty or 1; local ok,e=ReaperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ReaperMaker.woodStock=ReaperMaker.woodStock-d.woodCost*qty end; if d.ironCost then ReaperMaker.ironStock=ReaperMaker.ironStock-d.ironCost*qty end; if d.silverCost then ReaperMaker.silverStock=ReaperMaker.silverStock-d.silverCost*qty end; if d.goldCost then ReaperMaker.goldStock=ReaperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ReaperMaker.jewelStock=ReaperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ReaperMaker.pearlStock=ReaperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ReaperMaker.maker then t=math.max(1,t-math.floor(ReaperMaker.maker.skill/12)) end; table.insert(ReaperMaker.activeMaking,{id="reaper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ReaperMaker.completeMaking(m) local q=1.0+(ReaperMaker.getQualityBonus()/100); if ReaperMaker.maker then q=q+(ReaperMaker.maker.skill/140) end; q=math.min(2.5,q); ReaperMaker.productStock[m.productType]=(ReaperMaker.productStock[m.productType] or 0)+m.quantity; ReaperMaker.totalProducts=ReaperMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ReaperMaker.maker then ReaperMaker.maker.itemsMade=ReaperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ReaperMaker.maker.skill=math.min(100,ReaperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žetveni stroj izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"reaper.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function ReaperMaker.update(dt) if not _G.state then return end; ReaperMaker.dayTimer=ReaperMaker.dayTimer+dt; if ReaperMaker.dayTimer>=30 then ReaperMaker.dayTimer=0; for i=#ReaperMaker.activeMaking,1,-1 do local m=ReaperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ReaperMaker.completeMaking(m); table.remove(ReaperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ReaperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ReaperMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ReaperMaker.getStats() return {woodStock=ReaperMaker.woodStock,ironStock=ReaperMaker.ironStock,silverStock=ReaperMaker.silverStock,goldStock=ReaperMaker.goldStock,jewelStock=ReaperMaker.jewelStock,pearlStock=ReaperMaker.pearlStock,productStock=ReaperMaker.productStock,numBuildings=#ReaperMaker.buildings,hasMaker=ReaperMaker.maker~=nil,makerName=ReaperMaker.maker and ReaperMaker.maker.name or "—",makerSkill=ReaperMaker.maker and ReaperMaker.maker.skill or 0,activeMaking=#ReaperMaker.activeMaking,totalProducts=ReaperMaker.totalProducts} end
return ReaperMaker
